1	// Package audio provides audio container/codec helpers for AI providers.
2	//
3	// The motivating use case is Gemini transcription: Gemini's audio inputs
4	// require WAV/MP3/AIFF/AAC/OGG/FLAC, but browser MediaRecorder defaults to
5	// WebM/Opus. This package converts WebM/Opus into 16-bit PCM WAV using
6	// pure-Go decoders — no ffmpeg or other system dependency.
7	package audio
8	
9	import (
10		"bytes"
11		"encoding/binary"
12		"io"
13		"strings"
14	
15		"github.com/at-wat/ebml-go"
16		"github.com/at-wat/ebml-go/webm"
17		"github.com/pion/opus"
18		"github.com/pkg/errors"
19	)
20	
21	const (
22		opusOutputSampleRate = 48000
23		// maxOpusPacketSamples is Opus's spec maximum: 120 ms at 48 kHz.
24		maxOpusPacketSamples = 5760
25		// opusCodecID is the WebM TrackEntry CodecID for an Opus audio track.
26		opusCodecID = "A_OPUS"
27		// opusHeadMinLength is the minimum size of the OpusHead identification
28		// header stored in TrackEntry.CodecPrivate.
29		opusHeadMinLength = 19
30	)
31	
32	// WebMOpusToWAV decodes a WebM/Opus file into 16-bit PCM WAV bytes.
33	//
34	// The output is mono or stereo at 48 kHz (Opus's native decode rate),
35	// regardless of the original encoder's hint. Pre-skip samples declared in
36	// the OpusHead are discarded to avoid the encoder's startup padding.
37	//
38	// The function reads the entire WebM document into memory; callers should
39	// enforce their own size limits before invoking it.
40	func WebMOpusToWAV(input []byte) ([]byte, error) {
41		var doc struct {
42			Header  webm.EBMLHeader `ebml:"EBML"`
43			Segment webm.Segment    `ebml:"Segment"`
44		}
45		if err := ebml.Unmarshal(bytes.NewReader(input), &doc); err != nil && !errors.Is(err, io.EOF) {
46			return nil, errors.Wrap(err, "parse webm")
47		}
48	
49		track := findOpusTrack(doc.Segment.Tracks.TrackEntry)
50		if track == nil {
51			return nil, errors.New("webm has no Opus audio track")
52		}
53		if len(track.CodecPrivate) < opusHeadMinLength {
54			return nil, errors.Errorf("invalid OpusHead: expected at least %d bytes, got %d", opusHeadMinLength, len(track.CodecPrivate))
55		}
56	
57		channels := int(track.Audio.Channels)
58		if channels < 1 || channels > 2 {
59			return nil, errors.Errorf("unsupported Opus channel count: %d", channels)
60		}
61		preSkip := int(binary.LittleEndian.Uint16(track.CodecPrivate[10:12]))
62	
63		decoder := opus.NewDecoder()
64		if err := decoder.Init(opusOutputSampleRate, channels); err != nil {
65			return nil, errors.Wrap(err, "init opus decoder")
66		}
67	
68		pcm := make([]int16, 0, 1<<16)
69		frame := make([]int16, maxOpusPacketSamples*channels)
70	
71		decodeBlock := func(block ebml.Block) error {
72			if block.TrackNumber != track.TrackNumber {
73				return nil
74			}
75			for _, packet := range block.Data {
76				if len(packet) == 0 {
77					continue
78				}
79				n, err := decoder.DecodeToInt16(packet, frame)
80				if err != nil {
81					return errors.Wrap(err, "decode opus packet")
82				}
83				pcm = append(pcm, frame[:n*channels]...)
84			}
85			return nil
86		}
87	
88		for _, cluster := range doc.Segment.Cluster {
89			for _, sb := range cluster.SimpleBlock {
90				if err := decodeBlock(sb); err != nil {
91					return nil, err
92				}
93			}
94			for _, bg := range cluster.BlockGroup {
95				if err := decodeBlock(bg.Block); err != nil {
96					return nil, err
97				}
98			}
99		}
100	
101		skip := min(preSkip*channels, len(pcm))
102		pcm = pcm[skip:]
103	
104		return encodeWAV(pcm, opusOutputSampleRate, channels), nil
105	}
106	
107	// IsWebMContentType reports whether the MIME type is WebM audio.
108	// Both "audio/webm" and "audio/webm; codecs=opus" return true.
109	func IsWebMContentType(contentType string) bool {
110		contentType = strings.TrimSpace(contentType)
111		if contentType == "" {
112			return false
113		}
114		if i := strings.IndexByte(contentType, ';'); i >= 0 {
115			contentType = contentType[:i]
116		}
117		return strings.EqualFold(strings.TrimSpace(contentType), "audio/webm")
118	}
119	
120	func findOpusTrack(entries []webm.TrackEntry) *webm.TrackEntry {
121		for i := range entries {
122			entry := &entries[i]
123			if entry.CodecID == opusCodecID && entry.Audio != nil {
124				return entry
125			}
126		}
127		return nil
128	}
