130	// encodeWAV writes a standard RIFF/WAVE container around 16-bit PCM samples.
131	// Reference layout: http://soundfile.sapp.org/doc/WaveFormat/
132	func encodeWAV(samples []int16, sampleRate, channels int) []byte {
133		const bitsPerSample = 16
134		const bytesPerSample = bitsPerSample / 8
135		blockAlign := channels * bytesPerSample
136		byteRate := sampleRate * blockAlign
137		dataSize := len(samples) * bytesPerSample
138	
139		buf := bytes.NewBuffer(make([]byte, 0, 44+dataSize))
140		buf.WriteString("RIFF")
141		_ = binary.Write(buf, binary.LittleEndian, uint32(36+dataSize))
142		buf.WriteString("WAVE")
143	
144		buf.WriteString("fmt ")
145		_ = binary.Write(buf, binary.LittleEndian, uint32(16))
146		_ = binary.Write(buf, binary.LittleEndian, uint16(1)) // PCM
147		_ = binary.Write(buf, binary.LittleEndian, uint16(channels))
148		_ = binary.Write(buf, binary.LittleEndian, uint32(sampleRate))
149		_ = binary.Write(buf, binary.LittleEndian, uint32(byteRate))
150		_ = binary.Write(buf, binary.LittleEndian, uint16(blockAlign))
151		_ = binary.Write(buf, binary.LittleEndian, uint16(bitsPerSample))
152	
153		buf.WriteString("data")
154		_ = binary.Write(buf, binary.LittleEndian, uint32(dataSize))
155		_ = binary.Write(buf, binary.LittleEndian, samples)
156	
157		return buf.Bytes()
158	}
